/** Module ke naam, utne hi kram me jitne course me padhaye jaate hain. */
export const BANK_MODULES = ["Fundamentals","Windows 11","Internet & Cloud","Google Workspace","AI Productivity","MS Word","MS Excel","PowerPoint",
  /* AI Automation Pro — chaaron module ki Book se */
  "Automation Ki Basics","n8n — Automation Ka Engine","AI + WhatsApp Business Machine","Real Business Projects Aur Earning"];

/**
 * Kisi module me se utne sawaal uthata hai jitne maange gaye — har baar alag,
 * taaki do batch ko ek jaisa paper na mile.
 * @param {string} module  "" ho to saare module se
 * @param {number} count
 */
export function pickQuestions(module, count) {
  const pool = module ? QUESTION_BANK.filter((x) => x.m === module) : QUESTION_BANK.slice();
  /* Fisher-Yates — pool ki apni copy par, taaki asli bank na bigde. */
  const arr = pool.slice();
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr.slice(0, Math.max(1, Math.min(count, arr.length)));
}

/** Har module me kitne sawaal hain — dropdown me dikhane ke liye. */
export function bankCounts() {
  const out = {};
  QUESTION_BANK.forEach((x) => { out[x.m] = (out[x.m] || 0) + 1; });
  return out;
}
